const normWa=w=>{let d=String(w||'').replace(/\D/g,'');if(d.startsWith('0'))d='62'+d.slice(1);else if(d.startsWith('8'))d='62'+d;return d};
const fWa=w=>{let d=String(w||'');if(d.startsWith('62'))d='0'+d.slice(2);return d.replace(/^(\d{4})(\d{4})(\d+)$/,'$1-$2-$3')};
