const ov=(a,b,gap)=>a[0]<b[1]+gap&&b[0]<a[1]+gap;
function rng(seed){return function(){seed|=0;seed=seed+0x6D2B79F5|0;let t=Math.imul(seed^seed>>>15,1|seed);t=t+Math.imul(t^t>>>7,61|t)^t;return((t^t>>>14)>>>0)/4294967296}}
function pctTxt(a,b){if(!b)return a?'<span class="up">baru</span>':'<span class="muted">—</span>';const p=Math.round((a-b)/Math.abs(b)*100);return p>=0?`<span class="up">▲ ${p}%</span>`:`<span class="down">▼ ${Math.abs(p)}%</span>`}

