let SNAP=null,_ft=null,_flushing=false,_again=false,SYNC={s:'ok',t:0};
function snapAll(){SNAP={settings:JSON.stringify(S.settings)};for(const c of['bookings','kas','blokir'])SNAP[c]=new Map(S[c].map(x=>[x.id,JSON.stringify(x)]))}
function diffOps(){
  const ops=[];
  const s=JSON.stringify(S.settings);if(s!==SNAP.settings)ops.push({c:'settings',v:S.settings,_j:s});
  for(const c of['bookings','kas','blokir']){
    const seen=new Set();
    for(const x of S[c]){seen.add(x.id);const j=JSON.stringify(x);if(SNAP[c].get(x.id)!==j)ops.push({c,id:x.id,v:x,_j:j})}
    for(const id of SNAP[c].keys())if(!seen.has(id))ops.push({c,id,v:null})
  }
  return ops;
}
function save(){if(MODE!=='admin'||!S)return;SYNC.s='dirty';paintSync();clearTimeout(_ft);_ft=setTimeout(flush,300)}
async function flush(){
  if(_flushing){_again=true;return}
  const ops=diffOps();if(!ops.length){SYNC.s='ok';SYNC.t=Date.now();paintSync();return}
  _flushing=true;SYNC.s='save';paintSync();
  const r=await api('ops',{ops:ops.map(o=>({c:o.c,id:o.id,v:o.v}))});
  _flushing=false;
  if(r.ok){for(const o of ops){if(o.c==='settings')SNAP.settings=o._j;else if(o.v===null)SNAP[o.c].delete(o.id);else SNAP[o.c].set(o.id,o._j)}SYNC.s=(_again||diffOps().length)?'dirty':'ok';SYNC.t=Date.now()}
  else if(r.err==='auth'){SYNC.s='err';return adminLogout(true)}
  else{SYNC.s='err';toast(r.msg||'Gagal menyimpan. Coba lagi.');setTimeout(()=>{if(SYNC.s==='err')flush()},5000)}
  paintSync();
  if(_again||SYNC.s==='dirty'){_again=false;_ft=setTimeout(flush,200)}
}
function paintSync(){const el=document.getElementById('sync');if(!el)return;const m={ok:'Tersimpan',dirty:'Menyimpan…',save:'Menyimpan…',err:'Gagal tersimpan, mencoba lagi'};el.textContent=m[SYNC.s]||'';el.dataset.s=SYNC.s}
