/* ================= availability ================= */
function blocksFor(date){
  const st=S.settings, ex=st.pengecualian.find(e=>e.tgl===date);
  const raw=ex?(ex.tipe==='libur'?[]:ex.blok):(st.jam[pd(date).getDay()]||[]);
  return raw.map(b=>[toMin(b[0]),toMin(b[1])]).filter(b=>b[1]>b[0]).sort((a,b)=>a[0]-b[0]);
}
function minDur(){return Math.min(...S.settings.layanan.map(l=>+l.durasi||60),+S.settings.durasiDasar||60)}
function stepMin(){const st=S.settings;return st.interval==='auto'?(+st.durasiDasar||60)+(+st.jeda||0):Math.max(5,+st.interval||30)}
function candidates(date){
  const out=[],md=minDur(),step=stepMin();
  for(const[a,b] of blocksFor(date))for(let t=a;t+md<=b;t+=step)out.push(t);
  return [...new Set(out)].sort((x,y)=>x-y);
}
function occ(b){const s=toMin(b.jam),buf=b.lokasi==='rumah'?(+b.buffer||0):0;return[s-buf,s+b.durasi+buf]}
function slotStatus(date,t,dur,lok,opt={}){
  const st=S.settings,buf=lok==='rumah'?(+st.hv.buffer||0):0;
  if(!opt.admin){
    if(tsOf(date,toHM(t))<Date.now()+(+st.minLeadJam||0)*36e5)return'lewat';
    if(dayDiff(todayStr(),date)>=(+st.maxHari||30))return'lewat';
  }
  if(!blocksFor(date).some(([a,b])=>t>=a&&t+dur<=b))return'pendek';
  const me=[t-buf,t+dur+buf],gap=+st.jeda||0;
  for(const m of S.blokir)if(m.tgl===date&&ov(me,[toMin(m.dari),toMin(m.sampai)],0))return'blok';
  let n=0,hit=null;
  for(const b of S.bookings){if(b.tgl!==date||!LOCK.has(b.status)||b.id===opt.except)continue;n++;if(!hit&&ov(me,occ(b),gap))hit=b}
  if(hit)return hit.status==='MENUNGGU'?'ditahan':'terisi';
  if(n>=(+st.maxSesi||99))return'penuh';
  return'ok';
}
function slotView(date,t,dur,lok){
  const s=slotStatus(date,t,dur,lok);
  if(s==='ok')return'ok';
  if(s==='lewat')return'hide';
  const s0=slotStatus(date,t,minDur(),'studio');
  if(s0==='ok')return'kurang';
  if(s0==='pendek'||s0==='lewat')return'hide';
  return s0==='ditahan'?'ditahan':'terisi';
}
function dayInfo(date,dur,lok){
  if(!blocksFor(date).length){const ex=S.settings.pengecualian.find(e=>e.tgl===date);return{n:0,off:true,label:ex?'Tutup':'Libur'}}
  const c=candidates(date);let n=0,lew=0;
  for(const t of c){const s=slotStatus(date,t,dur,lok);if(s==='ok')n++;else if(s==='lewat')lew++}
  return{n,off:false,label:n?`${n} jam`:(lew===c.length?'Tutup':'Penuh')};
}
function refreshExpiry(){
  const now=Date.now();let ch=false;
  for(const b of S.bookings)if(b.status==='MENUNGGU'&&now>b.holdUntil){b.status='KEDALUWARSA';if(MODE==='admin'&&SNAP){const o=JSON.parse(SNAP.bookings.get(b.id)||'null');if(o){o.status='KEDALUWARSA';SNAP.bookings.set(b.id,JSON.stringify(o))}}ch=true}
  return ch;
}
function due(b){if(b.status==='MENUNGGU')return b.bayar.skema==='DP'?b.bayar.dp:b.total;return b.bayar.sisa}

/* ================= clinical helpers ================= */
function flags(b){
  const a=b.asesmen||{},f=[],g=(a.cederaGejala||[]).filter(x=>x!=='none');
  if(a.cedera==='ya'&&a.cederaKapan==='<3h'&&g.some(x=>['bengkak','memar','panas'].includes(x)))
    f.push(`Cedera baru (kurang dari 3 hari) di ${a.cederaBagian||'area keluhan'}: ${g.filter(x=>x!=='kebas').map(x=>GEJALA.find(y=>y.id===x).l.toLowerCase()).join(', ')}`);
  if(g.includes('kebas'))f.push('Ada mati rasa / kesemutan');
  if(+a.nyeri>=8)f.push(`Nyeri berat (${a.nyeri}/10)`);
  if(a.operasi==='ya')f.push(`Operasi dalam 12 bulan terakhir${a.operasiKet?': '+a.operasiKet:''}`);
  for(const k of a.kondisi||[])if(k!=='none'){const o=KONDISI.find(x=>x.id===k);if(o)f.push(o.l)}
  return f;
}
function eventNote(b,ev=b.event,tgl=b.tgl){
  if(!ev||!ev.tgl||!tgl||!['akan','baru'].includes(ev.status))return null;
  const d=dayDiff(tgl,ev.tgl);
  if(d<0){const x=-d;return{t:`${x} hari setelah ${ev.nama||'event'}`,s:x<=2?'Fokus pemulihan, tekanan ringan sampai sedang.':'Masa pemulihan pasca event.'}}
  if(d===0)return{t:`Event di hari yang sama`,s:'Sesi pre-event ringan dan singkat.'};
  if(d<=2)return{t:`Event H-${d}`,s:'Sesi pre-event ringan, hindari tekanan dalam.'};
  if(d<=7)return{t:`Event H-${d}`,s:'Masa taper, sesuaikan tekanan.'};
  return{t:`Event H-${d}`,s:''};
}
function visitNo(b){return S.bookings.filter(x=>x.pasien.wa===b.pasien.wa&&x.status==='SELESAI'&&startTs(x)<startTs(b)).length+1}
function noShows(b){return S.bookings.filter(x=>x.pasien.wa===b.pasien.wa&&x.status==='TIDAK_DATANG'&&x.id!==b.id).length}
