/* ================= koneksi server ================= */
const MODE=window.MODE||'pasien';
const API_URL=(window.SM_CONFIG&&window.SM_CONFIG.api)||'';
let TOKEN='';try{TOKEN=sessionStorage.getItem('sm-tok')||''}catch(e){}
async function api(a,body){
  if(!API_URL)return{ok:false,err:'config',msg:'Alamat server belum diatur (config.js).'};
  const q=Object.assign({a},body||{});if(MODE==='admin'&&TOKEN&&a!=='login')q.t=TOKEN;
  for(let n=0;n<2;n++){
    try{
      const ctl=new AbortController(),to=setTimeout(()=>ctl.abort(),30000);
      const r=await fetch(API_URL,{method:'POST',headers:{'Content-Type':'text/plain;charset=utf-8'},body:JSON.stringify(q),signal:ctl.signal,redirect:'follow'});
      clearTimeout(to);
      const j=await r.json();return j;
    }catch(e){if(n===1)return{ok:false,err:'net',msg:'Tidak bisa terhubung ke server. Periksa sinyal internet lalu coba lagi.'}}
  }
}

