function chipsF(path,opts,o={}){
  const cur=getPath(P.d,path);
  return `<div class="chips" role="group">${opts.map(x=>{const v=typeof x==='string'?x:x.id,l=typeof x==='string'?x:x.l;const on=o.multi?(cur||[]).includes(v):cur===v;
    return `<button type="button" class="chip" data-act="pick" data-f="${path}" data-v="${esc(v)}"${o.multi?' data-multi="1"':''}${o.excl?` data-excl="${o.excl}"`:''} aria-pressed="${on}">${esc(l)}</button>`}).join('')}</div>`;
}
const fieldIn=(label,path,attrs='',hint='')=>`<label class="field"><span>${label}</span><input class="in" id="f-${path.replace(/\./g,'-')}" data-f="${path}" value="${esc(getPath(P.d,path))}" ${attrs}>${hint?`<small>${hint}</small>`:''}</label>`;

function pHeader(){
  const st=S.settings,bl=blocksFor(todayStr());
  return `<header class="p-head"><div class="inner gut"><div class="tape t1"></div><div class="tape t2"></div>
    <span class="eyebrow" style="position:relative">Reservasi online</span>
    <h1 class="logo-wrap"><img class="logo-full" src="${LOGO}" width="1000" height="381" alt="${esc(st.nama)} ${esc(st.kota||'')}"></h1>
    <p class="brand-sub">${esc(st.tagline)}</p>
    <div class="p-meta"><span>${ICON.clock}Hari ini: ${bl.length?bl.map(([a,b])=>toHM(a)+'–'+toHM(b)).join(', '):'tutup'}</span>${st.alamat?`<span>${ICON.pin}${esc(st.alamat)}</span>`:''}${st.hv.aktif?`<span>${ICON.home}Bisa home visit</span>`:''}</div>
    <div class="btn-row" style="position:relative"><button class="btn btn-s btn-sm" data-act="cek-open">Cek status booking</button></div>
  </div></header>`;
}
function renderPasien(){
  refreshExpiry();
  if(!P.d)P.d=newDraft();
  app.innerHTML=`${pHeader()}<div class="p-wrap gut"><section class="card book" id="book">${P.kode?pStatus():pFlow()}</section>${pInfo()}</div>`;
  afterRender();
}
function renderBook(){const el=$('#book');if(!el)return renderPasien();el.innerHTML=P.kode?pStatus():pFlow();afterRender()}
function rerenderStep(){const sb=$('#stepbody');if(!sb)return renderBook();const sc=$('#dates')?.scrollLeft;sb.innerHTML=PSTEP[P.step]();if(sc!=null&&$('#dates'))$('#dates').scrollLeft=sc;const e=$('#perr');if(e)e.hidden=true}
function pFlow(){
  const s=P.step;
  return `<div class="step-top"><div><span class="eyebrow">Langkah ${s+1} dari ${STEPS.length}</span><h2>${STEPS[s]}</h2></div>${s>0?`<span class="muted" style="font-size:.85rem">${esc(svc(P.d.layanan).nama)}${P.d.jam?` · ${fTglS(P.d.tgl)}, ${P.d.jam}`:''}</span>`:''}</div>
  <div class="steps" aria-hidden="true">${STEPS.map((_,i)=>`<i class="${i<=s?'on':''}"></i>`).join('')}</div>
  <div id="stepbody" style="display:flex;flex-direction:column;gap:18px">${PSTEP[s]()}</div>
  <p class="err" id="perr" role="alert" ${P.err?'':'hidden'}>${esc(P.err)}</p>
  <div class="nav-row">${s>0?`<button class="btn btn-s" data-act="p-back">${ICON.left}Kembali</button>`:'<span></span>'}
  ${s<STEPS.length-1?`<button class="btn btn-p" data-act="p-next">Lanjut${ICON.right}</button>`:`<button class="btn btn-p" data-act="p-submit">Kirim booking</button>`}</div>`;
}
function p0(){
  const st=S.settings,d=P.d;
  return `<div class="sect"><div class="svc-grid">${st.layanan.map(l=>`<button class="svc" data-act="pick" data-f="layanan" data-v="${esc(l.id)}" aria-pressed="${d.layanan===l.id}"><span class="svc-dur">${l.durasi}<small>MENIT</small></span><span class="svc-name">${esc(l.nama)}</span><span class="svc-ket">${esc(l.ket)}</span><span class="svc-price">${rp(l.harga)}</span></button>`).join('')}</div></div>
  ${st.hv.aktif?`<div class="sect"><h3>Di mana sesinya?</h3><div class="loc-grid">
    <button class="loc" data-act="pick" data-f="lokasi" data-v="studio" aria-pressed="${d.lokasi==='studio'}">${ICON.pin}<span><b>Datang ke studio</b><small class="muted">${esc(st.alamat||'Alamat dikirim lewat WhatsApp')}</small></span></button>
    <button class="loc" data-act="pick" data-f="lokasi" data-v="rumah" aria-pressed="${d.lokasi==='rumah'}">${ICON.home}<span><b>Terapis datang ke rumah</b><small class="muted">Tambah ${rp(st.hv.biaya)} · ${esc(st.hv.area)}</small></span></button>
  </div></div>`:''}`;
}
function p1(){
  const st=S.settings,d=P.d,L=svc(d.layanan),t0=todayStr(),days=[];
  for(let i=0;i<(+st.maxHari||21);i++)days.push(addDays(t0,i));
  const info=days.map(x=>[x,dayInfo(x,L.durasi,d.lokasi)]);
  if(!d.tgl||!days.includes(d.tgl))d.tgl=(info.find(([,i])=>i.n>0)||[t0])[0];
  return `<p class="muted">${esc(L.nama)} · ${L.durasi} menit · ${d.lokasi==='rumah'?'home visit':'di studio'} <button class="linkbtn" data-act="p-go" data-v="0">Ubah</button></p>
  <div class="sect"><div class="dates" id="dates">${info.map(([x,i])=>{const dd=pd(x);return `<button class="date ${i.n?'':'off'}" data-act="p-date" data-v="${x}" aria-pressed="${x===d.tgl}" aria-label="${fTgl(x)}, ${i.n?i.n+' jam tersedia':i.label}"><span class="dn">${x===t0?'Hari ini':HR[dd.getDay()]}</span><span class="dd">${dd.getDate()}</span><span class="ds">${i.n?BLN[dd.getMonth()]+' · '+i.n:i.label}</span></button>`}).join('')}</div></div>
  <div class="sect" id="slotbox">${slotsHtml()}</div>`;
}
function slotsHtml(){
  const st=S.settings,d=P.d,L=svc(d.layanan),ex=st.pengecualian.find(e=>e.tgl===d.tgl);
  const head=`<h3>${fTgl(d.tgl)}</h3>`;
  if(!blocksFor(d.tgl).length)return head+`<div class="empty">Tutup${ex?': '+esc(ex.ket):''}. Silakan pilih tanggal lain.</div>`;
  const items=candidates(d.tgl).map(t=>({t,v:slotView(d.tgl,t,L.durasi,d.lokasi)})).filter(x=>x.v!=='hide');
  if(!items.length)return head+`<div class="empty">Jam praktik di tanggal ini sudah lewat atau terlalu dekat. Pilih tanggal lain.</div>`;
  if(d.jam&&!items.some(x=>x.v==='ok'&&toHM(x.t)===d.jam))d.jam=null;
  const nAct=S.bookings.filter(b=>b.tgl===d.tgl&&LOCK.has(b.status)).length;
  const hasK=items.some(x=>x.v==='kurang');
  return head+`<div class="slots">${items.map(({t,v})=>{
    if(v==='ok')return `<button class="slot" data-act="p-slot" data-v="${toHM(t)}" aria-pressed="${d.jam===toHM(t)}"><b>${toHM(t)}</b><small>s/d ${toHM(t+L.durasi)}</small></button>`;
    const lab={ditahan:'Sedang dipesan',terisi:'Terisi',kurang:'Waktu kurang'}[v];
    return `<button class="slot ${v==='ditahan'?'held':''}" disabled><b>${toHM(t)}</b><small>${v==='kurang'?'':ICON.lock}${lab}</small></button>`}).join('')}</div>
  <div class="legend"><span><i class="sw"></i>Tersedia</span><span><i class="sw" style="border-style:dashed;background:var(--surface-2)"></i>Terisi / sedang dipesan (terkunci otomatis)</span></div>
  ${nAct>=(+st.maxSesi||99)?`<div class="note-box">Kuota ${st.maxSesi} sesi di tanggal ini sudah penuh.</div>`:''}
  ${hasK?`<p class="muted" style="font-size:.84rem">“Waktu kurang”: jam itu kosong, tapi tidak cukup untuk ${L.durasi} menit${d.lokasi==='rumah'?` plus waktu tempuh ${st.hv.buffer} menit`:''} dan istirahat terapis sebelum jadwal berikutnya.</p>`:''}`;
}
function p2(){
  const d=P.d,u=umur(d.lahir);
  return `<div class="grid2">${fieldIn('Nama lengkap','nama','autocomplete="name"')}${fieldIn('Nomor WhatsApp','wa','type="tel" inputmode="tel" autocomplete="tel" placeholder="08xx-xxxx-xxxx"','Dipakai untuk konfirmasi dan pengingat jadwal.')}</div>
  <div class="grid2">${fieldIn('Tanggal lahir','lahir',`type="date" max="${todayStr()}"`,u!=null&&u<18?'Di bawah 18 tahun: mohon datang dengan pendamping.':'')}<div class="field"><span>Jenis kelamin</span>${chipsF('jk',[{id:'L',l:'Laki-laki'},{id:'P',l:'Perempuan'}])}</div></div>
  ${d.lokasi==='rumah'?`<div class="sect"><h3>${ICON.home} Alamat home visit</h3><label class="field"><span>Alamat lengkap</span><textarea class="in" id="f-alamat" data-f="alamat" rows="2">${esc(d.alamat)}</textarea></label>${fieldIn('Patokan (opsional)','patokan','placeholder="contoh: pagar hitam, depan musala"')}
    <label class="field"><span>Tautan lokasi Google Maps</span><input class="in" id="f-maps" data-f="maps" type="url" inputmode="url" autocomplete="off" placeholder="https://maps.app.goo.gl/…" value="${esc(d.maps)}"><small>Supaya terapis tidak tersesat. Buka Google Maps, tekan lama titik rumah Anda, pilih <b>Bagikan</b>, lalu tempel tautannya di sini.</small></label>
    <div class="btn-row"><a class="btn btn-g btn-sm" id="maps-find" href="${d.alamat.trim()?mapsSearch(d.alamat.trim()):'#'}" target="_blank" rel="noopener" ${d.alamat.trim()?'':'aria-disabled="true"'}>${ICON.pin}Cari alamat di Google Maps</a></div>
    <small class="muted">Area layanan: ${esc(S.settings.hv.area)}.</small></div>`:''}`;
}
function p3(){
  const a=P.d.as;
  return `<div class="sect"><label class="field"><span>Keluhan utama</span><textarea class="in" id="f-keluhan" data-f="as.keluhan" rows="3" placeholder="contoh: betis kiri kencang setelah long run 25 km, terasa saat menanjak">${esc(a.keluhan)}</textarea></label></div>
  <div class="sect"><h4>Area yang dikeluhkan</h4>${chipsF('as.area',AREA,{multi:true})}</div>
  <div class="sect"><h4>Skala nyeri saat ini</h4><div class="scale">${Array.from({length:11},(_,i)=>`<button type="button" data-act="pick" data-f="as.nyeri" data-v="${i}" data-num="1" aria-pressed="${+a.nyeri===i}">${i}</button>`).join('')}</div><div class="scale-l"><span>0 · tidak nyeri</span><span>10 · nyeri sekali</span></div></div>
  <div class="sect"><h4>Sudah dirasakan sejak</h4>${chipsF('as.sejak',SEJAK)}</div>
  <div class="sect"><h4>Pernah atau sedang cedera?</h4>${chipsF('as.cedera',[{id:'tidak',l:'Tidak'},{id:'ya',l:'Ya'}])}
    ${a.cedera==='ya'?`<div class="sub">${fieldIn('Bagian tubuh yang cedera','as.cederaBagian','placeholder="contoh: pergelangan kaki kanan"')}
      <div class="field"><span>Penyebab</span>${chipsF('as.cederaPenyebab',PENYEBAB)}</div>
      <div class="field"><span>Kapan terjadi</span>${chipsF('as.cederaKapan',KAPAN)}</div>
      <div class="field"><span>Yang dirasakan sekarang</span>${chipsF('as.cederaGejala',GEJALA,{multi:true,excl:'none'})}</div>
      <div class="field"><span>Sudah ditangani oleh</span>${chipsF('as.ditangani',DITANGANI)}</div></div>`:''}</div>
  <div class="sect"><h4>Operasi dalam 12 bulan terakhir?</h4>${chipsF('as.operasi',[{id:'tidak',l:'Tidak'},{id:'ya',l:'Ya'}])}
    ${a.operasi==='ya'?`<div class="sub">${fieldIn('Operasi apa dan kapan','as.operasiKet','placeholder="contoh: ACL lutut kiri, Maret 2026"')}</div>`:''}</div>
  <div class="sect"><h4>Kondisi kesehatan yang perlu diketahui terapis</h4>${chipsF('as.kondisi',KONDISI.filter(k=>!k.jk||k.jk===P.d.jk),{multi:true,excl:'none'})}</div>
  <div class="sect"><h4>Olahraga utama</h4>${chipsF('as.olahraga',OLAHRAGA,{multi:true})}<div class="field"><span>Frekuensi latihan</span>${chipsF('as.frek',FREK)}</div></div>
  <div class="sect"><h4>Preferensi tekanan pijat</h4>${chipsF('as.tekanan',TEKANAN)}</div>`;
}
function p4(){
  const ev=P.d.ev,n=eventNote(null,ev,P.d.tgl);
  return `<div class="sect"><p class="muted">Terapis menyesuaikan jenis dan tekanan pijat dengan jarak ke hari lomba.</p>${chipsF('ev.status',[{id:'tidak',l:'Tidak ada'},{id:'akan',l:'Ya, akan ikut event'},{id:'baru',l:'Baru selesai event'}])}</div>
  ${['akan','baru'].includes(ev.status)?`<div class="sub">${fieldIn('Nama event','ev.nama','placeholder="contoh: Half marathon kota"')}
    <div class="grid2">${fieldIn('Tanggal event','ev.tgl','type="date"')}${fieldIn('Jenis / jarak','ev.jenis','placeholder="contoh: Lari 21K, sepeda 100 km"')}</div>
    ${n?`<div class="note-box">${ICON.flag} <b>${esc(n.t)}</b> dari jadwal sesi. ${esc(n.s)}</div>`:''}</div>`:''}`;
}
function p5(){
  const st=S.settings,d=P.d,L=svc(d.layanan),hv=d.lokasi==='rumah'?st.hv.biaya:0,total=L.harga+hv,dp=dpOf(total);
  const online=d.metode&&d.metode!=='tunai';
  const holdTxt=d.metode==='tunai'?`Jadwal ditahan sampai admin konfirmasi lewat WhatsApp, maksimal ${fDur(st.holdTunaiMenit)}. Bayar ${rp(total)} tunai saat sesi.`
    :online?`Jadwal ditahan ${fDur(st.holdMenit)} untuk pembayaran. Lewat batas, jadwal dilepas otomatis. Jadwal terkunci setelah admin mengecek pembayaran.`:'';
  return `<div class="sect"><dl class="sum"><dt>Layanan</dt><dd>${esc(L.nama)} · ${L.durasi} menit</dd><dt>Jadwal</dt><dd>${fTgl(d.tgl)}, ${d.jam}–${toHM(toMin(d.jam)+L.durasi)}</dd><dt>Lokasi</dt><dd>${d.lokasi==='rumah'?'Home visit · '+esc(d.alamat):'Studio'+(st.alamat?' · '+esc(st.alamat):'')}</dd><dt>Nama</dt><dd>${esc(d.nama)} · ${esc(fWa(normWa(d.wa)))}</dd></dl></div>
  <div class="sect"><div class="price-l"><span>${esc(L.nama)}</span><span>${rp(L.harga)}</span></div>${hv?`<div class="price-l"><span>Biaya home visit</span><span>${rp(hv)}</span></div>`:''}<div class="price-l tot"><span>Total</span><span>${rp(total)}</span></div></div>
  <div class="sect"><h3>Cara bayar</h3><div class="pay-opts">
    ${st.qrisAda?`<button class="loc" data-act="pick" data-f="metode" data-v="qris" aria-pressed="${d.metode==='qris'}"><span><b>QRIS</b><small class="muted">Semua e-wallet & m-banking</small></span></button>`:''}
    ${st.rekening.some(x=>x.no)?`<button class="loc" data-act="pick" data-f="metode" data-v="transfer" aria-pressed="${d.metode==='transfer'}"><span><b>Transfer bank</b><small class="muted">${esc(st.rekening.filter(x=>x.no).map(x=>x.bank).join(', '))}</small></span></button>`:''}
    <button class="loc" data-act="pick" data-f="metode" data-v="tunai" aria-pressed="${d.metode==='tunai'}"><span><b>Tunai di tempat</b><small class="muted">Perlu konfirmasi admin</small></span></button></div>
    ${online&&st.dpAktif?`<div class="field"><span>Bayar sekarang</span>${chipsF('skema',[{id:'DP',l:`DP ${st.dpPersen}% · ${rp(dp)}`},{id:'LUNAS',l:`Lunas · ${rp(total)}`}])}<small class="muted">${d.skema==='DP'?`Sisa ${rp(total-dp)} dibayar saat sesi.`:'Tidak ada tagihan lagi saat sesi.'}</small></div>`:''}
    ${holdTxt?`<div class="note-box">${ICON.clock} ${holdTxt}</div>`:''}</div>
  <div class="sect">
    <label class="check"><input type="checkbox" id="f-setuju1" data-f="setuju1" ${d.setuju1?'checked':''}><span>Saya setuju data keluhan dan kesehatan di atas dipakai terapis untuk menangani saya dan tidak dibagikan ke pihak lain.</span></label>
    <label class="check"><input type="checkbox" id="f-setuju2" data-f="setuju2" ${d.setuju2?'checked':''}><span>Saya memahami ketentuan: pembatalan dikenai potongan ${st.potonganBatal}% dari DP, dan keterlambatan mengurangi durasi sesi.</span></label></div>`;
}
const PSTEP=[p0,p1,p2,p3,p4,p5];
function validStep(s){
  const d=P.d,a=d.as;
  if(s===0){if(!d.layanan)return'Pilih layanan dulu.';if(d.lokasi==='rumah'&&!S.settings.hv.aktif)return'Home visit sedang tidak tersedia.'}
  if(s===1){if(!d.jam)return'Pilih jam yang tersedia.';if(slotStatus(d.tgl,toMin(d.jam),svc(d.layanan).durasi,d.lokasi)!=='ok')return'Jam itu baru saja terisi. Pilih jam lain.'}
  if(s===2){const m=[];if(d.nama.trim().length<3)m.push('nama');const w=normWa(d.wa);if(w.length<10||w.length>15||!w.startsWith('62'))m.push('nomor WhatsApp yang benar');if(!d.lahir||umur(d.lahir)<5||umur(d.lahir)>100)m.push('tanggal lahir');if(!d.jk)m.push('jenis kelamin');if(d.lokasi==='rumah'&&d.alamat.trim().length<8)m.push('alamat home visit');if(d.lokasi==='rumah'&&!mapsOk(d.maps))m.push('tautan Google Maps (maps.app.goo.gl atau google.com/maps)');if(m.length)return'Lengkapi: '+m.join(', ')+'.'}
  if(s===3){const m=[];if(a.keluhan.trim().length<5)m.push('keluhan utama');if(!a.area.length)m.push('area keluhan');if(!a.sejak)m.push('sejak kapan');if(!a.cedera)m.push('riwayat cedera');if(a.cedera==='ya'){if(!a.cederaBagian.trim())m.push('bagian yang cedera');if(!a.cederaKapan)m.push('kapan cedera');if(!a.cederaGejala.length)m.push('kondisi cedera sekarang')}if(!a.operasi)m.push('riwayat operasi');if(!a.kondisi.length)m.push('kondisi kesehatan (pilih "Tidak ada" bila tidak ada)');if(!a.olahraga.length)m.push('olahraga utama');if(m.length)return'Lengkapi: '+m.join(', ')+'.'}
  if(s===4){const e=d.ev;if(!e.status)return'Jawab pertanyaan event dulu.';if(e.status!=='tidak'&&(!e.nama.trim()||!e.tgl))return'Isi nama dan tanggal event.'}
  if(s===5){if(!d.metode)return'Pilih cara bayar.';if(!d.setuju1||!d.setuju2)return'Centang kedua persetujuan untuk melanjutkan.'}
  return'';
}
async function submitBooking(){
  if(P.busy)return;
  for(let s=0;s<6;s++){const e=validStep(s);if(e){P.err=e;if(s<P.step)P.step=s;if(s===1)P.d.jam=null;renderBook();return}}
  const d=P.d;
  const payload={layanan:d.layanan,lokasi:d.lokasi,tgl:d.tgl,jam:d.jam,metode:d.metode,skema:d.skema,
    pasien:{nama:d.nama.trim(),wa:normWa(d.wa),lahir:d.lahir,jk:d.jk,alamat:d.alamat.trim(),maps:d.lokasi==='rumah'?d.maps.trim():'',patokan:d.patokan.trim()},asesmen:clone(d.as),event:clone(d.ev)};
  P.busy=true;P.err='';renderBook();
  const r=await api('book',{b:payload});
  P.busy=false;
  if(!r.ok){
    P.err=r.msg||'Gagal mengirim booking.';
    if(r.err==='slot'){P.d.jam=null;P.step=1;await refreshPub()}
    renderBook();return;
  }
  const b=r.booking;P.bk=b;P.kode=b.kode;P.wa4=b.pasien.wa.slice(-4);P.bimg=null;
  try{localStorage.setItem(KEY+'-last',JSON.stringify({k:b.kode,w:P.wa4}))}catch(e){}
  P.d=newDraft();await refreshPub();
  renderPasien();window.scrollTo({top:0});
}
function waAdminText(b){
  const n=b.pasien.nama;
  return `Halo admin, saya ${n}. Booking ${b.kode}: ${b.layananNama}, ${fTgl(b.tgl)} pukul ${b.jam}${b.lokasi==='rumah'?' (home visit, lokasi: '+mapsOf(b.pasien)+')':''}. `+
    (b.bayar.metode==='tunai'?'Saya pilih bayar tunai di tempat, mohon konfirmasi jadwalnya.':`Saya sudah bayar ${rp(due(b))} lewat ${MET[b.bayar.metode]}, bukti terlampir.`);
}
function pStatus(){
  const st=S.settings,b=P.bk;
  if(!b){P.kode=null;return pFlow()}
  if(b.status==='MENUNGGU'&&Date.now()>b.holdUntil)b.status='KEDALUWARSA';
  const end=toHM(toMin(b.jam)+b.durasi),waUrl=`https://wa.me/${st.wa}?text=${encodeURIComponent(waAdminText(b))}`;
  const waBlock=!st.wa?'':`<div class="sect"><div class="btn-row"><a class="btn btn-p" href="${waUrl}" target="_blank" rel="noopener">${ICON.wa}Kirim ke admin lewat WhatsApp</a><button class="btn btn-s" data-act="copy" data-v="${esc(waAdminText(b))}">${ICON.copy}Salin pesan</button></div><small class="muted">WhatsApp admin: ${fWa(st.wa)}</small></div>`;
  let main='';
  if(b.status==='MENUNGGU'){
    if(b.bayar.metode==='tunai'){
      main=`<div class="warn-box"><b>Jadwal ditahan, menunggu konfirmasi admin.</b><br>Ditahan sampai pukul ${fJam(b.holdUntil)} (<span data-until="${b.holdUntil}">--:--</span> lagi). Admin akan menghubungi lewat WhatsApp. Pembayaran ${rp(b.total)} tunai saat sesi.</div>${waBlock}`;
    }else{
      const pay=b.bayar.metode==='qris'
        ?`<div class="qr-wrap">${P.qr?`<img class="qr-img" src="${P.qr}" alt="Kode QRIS ${esc(st.nama)}" width="336" height="336">`:`<div class="qr-img qr-load">Memuat QRIS…</div>`}<div style="display:flex;flex-direction:column;gap:4px;min-width:0"><b>Scan QRIS</b>${st.qrisNama?`<span class="muted">a.n. ${esc(st.qrisNama)}</span>`:''}<span>Nominal <b class="num">${rp(due(b))}</b></span><small class="muted">Setelah bayar, unggah bukti di bawah.</small></div></div>`
        :`<div style="display:flex;flex-direction:column;gap:8px"><span>Transfer <b class="num">${rp(due(b))}</b> ke salah satu rekening:</span>${st.rekening.map(x=>`<div class="rek"><span><b>${esc(x.bank)}</b> <span class="num">${esc(x.no)}</span><br><small class="muted">a.n. ${esc(x.an)}</small></span><button class="btn btn-s btn-sm" data-act="copy" data-v="${esc(x.no)}">${ICON.copy}Salin</button></div>`).join('')}</div>`;
      main=`<div class="sect"><span class="eyebrow">Selesaikan pembayaran dalam</span><span class="count" data-until="${b.holdUntil}">--:--</span><small class="muted">Batas pukul ${fJam(b.holdUntil)}. ${b.bayar.skema==='DP'?`DP ${rp(b.bayar.dp)}, sisa ${rp(b.total-b.bayar.dp)} saat sesi.`:'Pembayaran penuh.'}</small></div>
      <div class="sect">${pay}</div>
      <div class="sect"><label class="field"><span>Unggah bukti bayar</span><input type="file" class="in" id="bukti" accept="image/*"><small>Jadwal terkunci setelah admin mengecek pembayaran, bukan otomatis dari unggahan.</small></label>${P.bimg?`<img class="thumb" src="${P.bimg}" alt="Bukti bayar yang diunggah">`:''}${b.bukti&&!P.bimg?`<small class="muted">Bukti bayar sudah terkirim. Unggah lagi kalau ingin mengganti.</small>`:''}${P.uerr?`<p class="err" role="alert">${esc(P.uerr)}</p>`:''}</div>${waBlock}`;
    }
  }else if(CONF.includes(b.status)){
    main=`<div class="note-box">${ICON.lock} <b>Jadwal sudah terkunci.</b> ${b.bayar.sisa>0?`Sisa pembayaran ${rp(b.bayar.sisa)} dibayar saat sesi (tunai atau QRIS).`:'Pembayaran lunas.'}</div>
    <div class="sect"><h4>Persiapan</h4><ul style="margin:0;padding-left:18px;font-size:.92rem"><li>Pakai pakaian longgar; celana pendek untuk keluhan kaki.</li><li>Makan ringan 1–2 jam sebelum sesi.</li><li>Datang 10 menit lebih awal${b.lokasi==='rumah'?'; siapkan ruang sekitar 2×3 m untuk matras':''}.</li></ul></div>${waBlock}`;
  }else if(b.status==='KEDALUWARSA'){
    main=`<div class="warn-box"><b>Waktu tahan sudah habis, jadwal dilepas.</b> Kalau sudah terlanjur bayar, kirim bukti ke admin lewat WhatsApp supaya dicek.</div>${waBlock}`;
  }else if(b.status==='BATAL'){
    main=`<div class="note-box">Booking dibatalkan.${b.batal&&b.batal.refund?` Dana dikembalikan ${rp(b.batal.refund)}.`:''}</div>`;
  }else if(b.status==='SELESAI'){
    main=`<div class="note-box">${ICON.check} Sesi selesai. Terima kasih! Kalau ada keluhan lanjutan, kabari admin lewat WhatsApp.</div>`;
  }else main=`<div class="note-box">Status: ${ST[b.status].l}.</div>`;
  return `<div class="step-top"><div><span class="eyebrow">Status booking</span><h2>${esc(b.pasien.nama.split(' ')[0])}, ini kode booking kamu</h2></div>${pill(b.status)}</div>
  <div class="bib"><span class="pins"></span><div class="k">${b.kode}</div><div class="l">${esc(b.layananNama)}</div></div>
  <dl class="sum"><dt>Jadwal</dt><dd>${fTgl(b.tgl)}, ${b.jam}–${end}</dd><dt>Lokasi</dt><dd>${b.lokasi==='rumah'?'Home visit · '+esc(b.pasien.alamat)+(mapsOf(b.pasien)?` <a href="${esc(mapsOf(b.pasien))}" target="_blank" rel="noopener">Lihat di Maps</a>`:''):'Studio · '+esc(st.alamat)}</dd><dt>Total</dt><dd>${rp(b.total)} · ${SKEMA[b.bayar.skema]} · ${MET[b.bayar.metode]}</dd></dl>
  ${main}
  <div class="nav-row"><button class="btn btn-s" data-act="p-new">Buat booking baru</button><button class="btn btn-g" data-act="cek-refresh">Perbarui status</button></div>`;
}
function pInfo(){
  const st=S.settings,t=todayStr(),wd=pd(t).getDay();
  const ex=st.pengecualian.filter(e=>e.tgl>=t&&dayDiff(t,e.tgl)<=30).sort((a,b)=>a.tgl<b.tgl?-1:1);
  return `<section class="card info">
  <div><h3>Jam praktik</h3><table class="hours">${ORDER_HARI.map(i=>{const bl=st.jam[i]||[];return `<tr class="${i===wd?'today':''}"><td>${HARI[i]}</td><td>${bl.length?bl.map(b=>b[0]+'–'+b[1]).join('<br>'):'Libur'}</td></tr>`}).join('')}</table>
  ${ex.length?`<p class="muted" style="font-size:.84rem;margin-top:8px">${ex.map(e=>`${fTglS(e.tgl)}: ${e.tipe==='libur'?'tutup':'jam khusus '+e.blok.map(b=>b[0]+'–'+b[1]).join(', ')}`).join('<br>')}</p>`:''}</div>
  <div><h3>Lokasi</h3><ul>${st.alamat?`<li>Studio: ${esc(st.alamat)}</li>`:''}${st.hv.aktif?`<li>Home visit: ${esc(st.hv.area)}, tambahan ${rp(st.hv.biaya)}</li>`:''}${st.wa?`<li>WhatsApp admin: ${fWa(st.wa)}</li>`:''}</ul></div>
  <div><h3>Ketentuan</h3><ul><li>QRIS/transfer: jadwal ditahan ${fDur(st.holdMenit)}, terkunci setelah pembayaran dicek admin.</li>${st.dpAktif?`<li>Boleh DP ${st.dpPersen}%, sisanya dibayar saat sesi.</li>`:''}<li>Tunai di tempat: jadwal ditahan sampai admin konfirmasi (maks. ${fDur(st.holdTunaiMenit)}).</li><li>Pembatalan: potongan ${st.potonganBatal}% dari DP, sisanya dikembalikan.</li><li>Terlambat datang mengurangi durasi sesi.</li></ul></div>
  </section>`;
}
function readBukti(inp){
  const f=inp.files&&inp.files[0],b=P.bk;if(!f||!b)return;
  if(!/^image\//.test(f.type)){P.uerr='Pilih berkas gambar (foto atau tangkapan layar).';renderBook();return}
  const fr=new FileReader();P.uerr='';
  fr.onload=()=>{const img=new Image();
    img.onload=async()=>{const m=900,sc=Math.min(1,m/Math.max(img.width,img.height)),c=document.createElement('canvas');c.width=Math.round(img.width*sc);c.height=Math.round(img.height*sc);c.getContext('2d').drawImage(img,0,0,c.width,c.height);
      const data=c.toDataURL('image/jpeg',.72);toast('Mengunggah bukti…');
      const r=await api('bukti',{kode:P.kode,wa4:P.wa4,data});
      if(r.ok){P.bk=r.booking;P.bimg=data;P.uerr='';toast('Bukti terkirim ke admin')}else P.uerr=r.msg||'Gagal mengunggah bukti.';
      renderBook()};
    img.onerror=()=>{P.uerr='Gambar tidak bisa dibaca. Coba foto atau tangkapan layar lain.';renderBook()};img.src=fr.result};
  fr.readAsDataURL(f);
}
async function refreshPub(){
  const r=await api('pub');
  if(r.ok&&r.ready){S={settings:r.settings,bookings:r.slots,kas:[],blokir:r.blokir};S.skew=r.now-Date.now();return true}
  return r;
}
async function refreshMine(){
  if(!P.kode)return;const r=await api('mine',{kode:P.kode,wa4:P.wa4});
  if(r.ok){const ch=JSON.stringify(r.booking)!==JSON.stringify(P.bk);P.bk=r.booking;if(ch&&MODE==='pasien'&&!document.activeElement.matches('input,textarea'))renderBook()}
}
async function loadQris(){
  if(P.qr||P.qrTry||!P.bk||P.bk.bayar.metode!=='qris'||P.bk.status!=='MENUNGGU')return;
  P.qrTry=true;const r=await api('qris');if(r.ok){P.qr=r.data;renderBook()}
}

/* ================= admin ================= */
let A={tab:'hari',unlocked:false,bimg:{},f:'mendatang',q:'',lim:60,cal:null,calStart:null,finR:'6m',finB:'kas',finL:'semua',pendingDet:null};
let SH=null;
A.unlocked=!!TOKEN;
const TABS=[['hari','Hari ini','clock'],['jadwal','Jadwal','cal'],['booking','Booking','list'],['keuangan','Keuangan','chart'],['praktik','Jam praktik','sliders'],['pengaturan','Pengaturan','gear']];

function renderAdmin(){
  if(!A.unlocked){
    app.innerHTML=`<div class="gut"><form class="card pin" id="pinform"><span class="eyebrow">Panel admin / terapis</span><h2>Masukkan PIN</h2><input class="in" id="pin" type="password" inputmode="numeric" autocomplete="current-password" maxlength="12" aria-label="PIN"><p class="err" id="pinerr" role="alert">${esc(A.pinErr||'')}</p><button class="btn btn-p" ${A.pinBusy?'disabled':''}>${A.pinBusy?'Memeriksa…':'Masuk'}</button></form></div>`;
    return;
  }
  refreshExpiry();
  const now=Date.now(),pend=S.bookings.filter(b=>b.status==='MENUNGGU'||(CONF.includes(b.status)&&endTs(b)<now)).length;
  const body=(A.tab==='hari'?setupBanner():'')+{hari:tHari,jadwal:tJadwal,booking:tBooking,keuangan:tKeu,praktik:tPraktik,pengaturan:tSet}[A.tab]();
  app.innerHTML=`<div class="a-wrap gut"><nav class="a-nav" aria-label="Menu admin"><div class="who"><img class="who-logo" src="${LOGO}" width="1000" height="381" alt="${esc(S.settings.nama)} ${esc(S.settings.kota||'')}"><span class="eyebrow">Panel terapis</span></div>${TABS.map(([id,l,ic])=>`<button class="tab" data-act="tab" data-v="${id}" ${A.tab===id?'aria-current="page"':''}>${ICON[ic]}${l}${id==='hari'&&pend?`<span class="cnt">${pend}</span>`:''}</button>`).join('')}<button class="tab tab-out" data-act="logout">${ICON.left}Keluar</button></nav><section class="a-main">${body}</section></div>`;
  afterRender();
}
function setupBanner(){
  const st=S.settings,m=[];
  if(!st.wa)m.push('nomor WhatsApp admin');
  if(!st.alamat)m.push('alamat studio');
  if(!st.qrisAda&&!st.rekening.some(r=>r.no))m.push('QRIS atau rekening transfer (kalau belum, pasien hanya bisa memilih bayar tunai)');
  if(!m.length)return '';
  return `<div class="warn-box" style="margin-bottom:14px"><b>Lengkapi dulu sebelum dibagikan ke pasien:</b><ul style="margin:6px 0 8px;padding-left:18px">${m.map(x=>`<li>${x}</li>`).join('')}</ul><button class="btn btn-p btn-sm" data-act="tab" data-v="pengaturan">Buka Pengaturan</button></div>`;
}
function kpi(l,v,d){return `<div class="kpi"><span class="eyebrow">${l}</span><span class="v">${v}</span><span class="d">${d}</span></div>`}
function bRow(b,o={}){
  const fl=flags(b),ev=eventNote(b),e=toHM(toMin(b.jam)+b.durasi);
  return `<div class="row" role="button" tabindex="0" data-act="det" data-v="${b.id}">
    <span class="t">${o.date?fTglS(b.tgl):b.jam}<small>${o.date?b.jam+'–'+e:'s/d '+e}</small></span>
    <span class="m"><b>${esc(b.pasien.nama)}</b><span class="tags"><span>${esc(b.layananNama)}</span>${b.lokasi==='rumah'?`<span>${ICON.home} Home visit</span>`:''}${fl.length?`<span class="flag">${ICON.alert}${fl.length} catatan kesehatan</span>`:''}${ev?`<span class="evt">${ICON.flag}${esc(ev.t)}</span>`:''}${o.extra||''}</span></span>
    <span class="r">${o.noPill?'':pill(b.status)}${o.right||''}</span></div>`;
}
function tHari(){
  const t=todayStr(),now=Date.now();
  const today=S.bookings.filter(b=>b.tgl===t&&LOCK.has(b.status)&&b.status!=='MENUNGGU').sort(byStart);
  const wait=S.bookings.filter(b=>b.status==='MENUNGGU').sort((a,b)=>a.holdUntil-b.holdUntil);
  const open=S.bookings.filter(b=>CONF.includes(b.status)&&endTs(b)<now).sort(byStart);
  const besok=S.bookings.filter(b=>b.tgl===addDays(t,1)&&CONF.includes(b.status)).sort(byStart);
  const fu=S.bookings.filter(b=>b.status==='SELESAI'&&b.tgl===addDays(t,-2)).sort(byStart);
  const masuk=sum(S.kas.filter(k=>ymd(new Date(k.waktu))===t),k=>k.jumlah);
  const tagih=sum(today.filter(b=>CONF.includes(b.status)),b=>b.bayar.sisa);
  const next=today.find(b=>startTs(b)>now&&CONF.includes(b.status)),bl=blocksFor(t);
  const wRow=b=>bRow(b,{date:true,right:`<small class="muted">${b.bayar.metode==='tunai'?'tunai · ':''}sisa <span data-until="${b.holdUntil}">--:--</span></small>`});
  const sent=(b,k)=>(b.wa||{})[k];
  return `<div class="a-head"><div><span class="eyebrow">${fTgl(t)}</span><h2>Hari ini</h2></div><button class="btn btn-p btn-sm" data-act="m-new">${ICON.plus}Booking manual</button></div>
  <div class="kpis">${kpi('Sesi hari ini',today.length,bl.length?(next?`Berikutnya ${next.jam} · ${esc(next.pasien.nama.split(' ')[0])}`:'Tidak ada sesi lagi'):'Hari ini libur')}${kpi('Perlu tindakan',wait.length+open.length,`${wait.length} menunggu konfirmasi`)}${kpi('Uang masuk hari ini',rp(masuk),'dari buku kas')}${kpi('Ditagih saat sesi',rp(tagih),'sisa DP & tunai hari ini')}</div>
  <div class="cols"><div style="display:flex;flex-direction:column;gap:18px;min-width:0">
    <div class="panel"><div class="panel-h"><h3>Perlu tindakan</h3><small class="muted">Jadwal dilepas otomatis bila waktu tahan habis</small></div>
      <div class="rows">${wait.map(wRow).join('')}${open.map(b=>bRow(b,{date:true,extra:`<span class="flag">Sesi lewat, belum ditutup</span>`})).join('')||''}</div>${!wait.length&&!open.length?'<div class="empty">Semua beres.</div>':''}</div>
    <div class="panel"><div class="panel-h"><h3>Jadwal hari ini</h3><button class="btn btn-g btn-sm" data-act="tab" data-v="jadwal">Lihat linimasa${ICON.right}</button></div>
      ${today.length?`<div class="rows">${today.map(b=>bRow(b,{right:b.bayar.sisa>0&&CONF.includes(b.status)?`<small class="muted">tagih ${rp(b.bayar.sisa)}</small>`:''})).join('')}</div>`:`<div class="empty">${bl.length?'Belum ada sesi terkunci hari ini.':'Hari ini libur.'}</div>`}</div>
  </div><div style="display:flex;flex-direction:column;gap:18px;min-width:0">
    <div class="panel"><div class="panel-h"><h3>Pengingat H-1</h3><small class="muted">${fTglS(addDays(t,1))}</small></div>
      ${besok.length?`<div class="rows">${besok.map(b=>bRow(b,{noPill:true,right:sent(b,'h1')?`<span class="pill pill-ok">${ICON.check}Terkirim</span>`:`<button class="btn btn-s btn-sm" data-act="wa" data-v="${b.id}" data-tpl="h1">${ICON.wa}Kirim</button>`})).join('')}</div>`:'<div class="empty">Tidak ada sesi besok.</div>'}</div>
    <div class="panel"><div class="panel-h"><h3>Tanya kondisi</h3><small class="muted">2 hari setelah sesi</small></div>
      ${fu.length?`<div class="rows">${fu.map(b=>bRow(b,{noPill:true,right:sent(b,'kondisi')?`<span class="pill pill-ok">${ICON.check}Terkirim</span>`:`<button class="btn btn-s btn-sm" data-act="wa" data-v="${b.id}" data-tpl="kondisi">${ICON.wa}Kirim</button>`})).join('')}</div>`:'<div class="empty">Tidak ada.</div>'}
      <small class="muted">Saat ini pesan dikirim admin dengan sekali klik. Pengiriman otomatis bisa ditambah dengan layanan WA gateway.</small></div>
  </div></div>`;
}

/* ---------- detail sheet */
function waTpls(b){
  const st=S.settings,n=b.pasien.nama.split(' ')[0],L=`${fTgl(b.tgl)} pukul ${b.jam}`,lok=b.lokasi==='rumah'?`Terapis datang ke ${b.pasien.alamat}${mapsOf(b.pasien)?' ('+mapsOf(b.pasien)+')':''}.`:`Lokasi: ${st.alamat}.`;
  const sisa=b.bayar.sisa>0?`Sisa ${rp(b.bayar.sisa)} dibayar saat sesi (tunai/QRIS).`:'Pembayaran sudah lunas.';
  const area=((b.asesmen||{}).area||[]).slice(0,2).join(' dan ').toLowerCase()||'ototnya';
  return[
    {id:'bayar',l:'Ingatkan bayar',x:`Halo ${n}, booking ${b.kode} (${b.layananNama}, ${L}) masih menunggu pembayaran ${rp(due(b))}. Jadwal ditahan sampai pukul ${fJam(b.holdUntil)}. Setelah bayar, kirim buktinya di sini ya.`},
    {id:'konfirm',l:'Konfirmasi jadwal',x:`Halo ${n}, jadwal ${b.layananNama} kamu sudah terkunci: ${L}. ${sisa} ${lok} Sampai ketemu!`},
    {id:'h1',l:'Pengingat H-1',x:`Halo ${n}, mengingatkan jadwal ${b.layananNama} besok, ${L}. ${lok} Pakai pakaian longgar dan makan ringan 1–2 jam sebelumnya. ${sisa} Balas pesan ini kalau perlu pindah jadwal.`},
    {id:'pelunasan',l:'Info pelunasan',x:`Halo ${n}, untuk sesi ${L}, sisa pembayaran ${rp(b.bayar.sisa)} bisa dibayar tunai atau QRIS saat sesi. Terima kasih.`},
    {id:'kondisi',l:'Tanya kondisi',x:`Halo ${n}, bagaimana kondisi ${area} setelah sesi ${fTglS(b.tgl)}? Kalau masih ada keluhan atau mau jadwalkan sesi berikutnya, kabari di sini ya.`},
    {id:'batal',l:'Pembatalan',x:`Halo ${n}, booking ${b.kode} (${L}) sudah dibatalkan.${b.batal&&b.batal.refund?` Dana ${rp(b.batal.refund)} akan dikembalikan.`:''} Semoga bisa jadwalkan lagi lain waktu.`},
    {id:'ulasan',l:'Minta ulasan',x:`Terima kasih sudah datang, ${n}! Kalau berkenan, bantu kami dengan ulasan singkat${st.ulasan?': '+st.ulasan:' di Google Maps'}.`},
    {id:'bebas',l:'Pesan bebas',x:`Halo ${n}, `},
  ];
}
const waHref=(wa,t)=>`https://wa.me/${wa}?text=${encodeURIComponent(t)}`;
function defaultTpl(b){if(b.status==='MENUNGGU')return'bayar';if(b.status==='SELESAI')return'kondisi';if(b.status==='BATAL')return'batal';if(b.tgl===addDays(todayStr(),1))return'h1';return'konfirm'}
function waPanel(b){
  const T=waTpls(b);if(!SH.tpl)SH.tpl=defaultTpl(b);if(SH.wtext==null)SH.wtext=(T.find(x=>x.id===SH.tpl)||T[0]).x;
  return `<div class="inline-pick"><b>${ICON.wa} Kirim WhatsApp ke ${esc(b.pasien.nama.split(' ')[0])}</b>
  <div class="chips">${T.map(x=>`<button class="chip sm" data-act="wa-tpl" data-v="${x.id}" aria-pressed="${SH.tpl===x.id}">${x.l}</button>`).join('')}</div>
  <textarea class="in" id="wa-text" rows="5" aria-label="Isi pesan">${esc(SH.wtext)}</textarea>
  <div class="btn-row"><a class="btn btn-p" id="wa-link" href="${waHref(b.pasien.wa,SH.wtext)}" target="_blank" rel="noopener" data-act="wa-sent">${ICON.wa}Buka WhatsApp</a><button class="btn btn-s" data-act="wa-copy">${ICON.copy}Salin</button><button class="btn btn-g" data-act="mode" data-v="">Tutup</button></div>
</div>`;
}
function pindahPanel(b){
  if(!SH.mv)SH.mv=b.tgl;
  const c=candidates(SH.mv).filter(t=>slotStatus(SH.mv,t,b.durasi,b.lokasi,{admin:true,except:b.id})==='ok');
  return `<div class="inline-pick"><b>Pindah jadwal</b><label class="field"><span>Tanggal baru</span><input type="date" class="in sm" id="mv-tgl" value="${SH.mv}" min="${todayStr()}" style="max-width:200px"></label>
  ${blocksFor(SH.mv).length?(c.length?`<div class="chips">${c.map(t=>`<button class="chip" data-act="mv-slot" data-v="${toHM(t)}">${toHM(t)}</button>`).join('')}</div>`:'<span class="muted">Tidak ada jam kosong yang cukup di tanggal ini.</span>'):'<span class="muted">Tanggal ini tutup.</span>'}
  <div class="btn-row"><button class="btn btn-g btn-sm" data-act="mode" data-v="">Batal pindah</button></div></div>`;
}
function actions(b){
  const st=S.settings,m=SH.mode,met=SH.met||b.bayar.metodeTerima||b.bayar.metode;
  if(m==='wa')return waPanel(b);
  if(m==='pindah')return pindahPanel(b);
  const metChips=`<div class="field"><span>Uang diterima lewat</span><div class="chips">${Object.entries(MET).map(([k,l])=>`<button class="chip sm" data-act="met" data-v="${k}" aria-pressed="${met===k}">${l}</button>`).join('')}</div></div>`;
  if(m==='batal'){const paid=b.bayar.dibayar,pot=Math.round(Math.min(paid,dpOf(b.total))*st.potonganBatal/100);
    return `<div class="inline-pick"><b>Batalkan booking ini?</b><span class="muted">${paid?`Sudah dibayar ${rp(paid)}.`:'Belum ada pembayaran.'} Jam ini langsung kosong lagi untuk pasien lain.</span><div style="display:flex;flex-direction:column;gap:8px">
      ${paid?`<button class="btn btn-d" data-act="batal-do" data-v="potong">Potong ${st.potonganBatal}% dari DP (${rp(pot)}), kembalikan ${rp(paid-pot)}</button><button class="btn btn-s" data-act="batal-do" data-v="penuh">Kembalikan penuh ${rp(paid)}</button><button class="btn btn-s" data-act="batal-do" data-v="hangus">Dana tidak dikembalikan</button>`:`<button class="btn btn-d" data-act="batal-do" data-v="penuh">Ya, batalkan</button>`}
      <button class="btn btn-g" data-act="mode" data-v="">Jangan batalkan</button></div></div>`}
  if(m==='nshow')return `<div class="inline-pick"><b>Tandai tidak datang?</b><span class="muted">Dana yang sudah dibayar (${rp(b.bayar.dibayar)}) tidak dikembalikan. Riwayat ini muncul di booking pasien berikutnya.</span><div class="btn-row"><button class="btn btn-d" data-act="nshow-do">Ya, tidak datang</button><button class="btn btn-g" data-act="mode" data-v="">Kembali</button></div></div>`;
  const wa=`<button class="btn btn-s btn-sm" data-act="mode" data-v="wa">${ICON.wa}WhatsApp</button>`;
  const ops=`<button class="btn btn-s btn-sm" data-act="mode" data-v="pindah">${ICON.cal}Pindah jadwal</button>${startTs(b)<Date.now()+36e5?`<button class="btn btn-s btn-sm" data-act="mode" data-v="nshow">Tidak datang</button>`:''}<button class="btn btn-s btn-sm" data-act="mode" data-v="batal">Batalkan</button>`;
  let main='',more='';
  if(b.status==='MENUNGGU'){
    const sk=b.bayar.skema,dp=b.bayar.dp||dpOf(b.total);
    const btns=sk==='TUNAI'?`<button class="btn btn-p" data-act="pay" data-v="KONF">${ICON.lock}Konfirmasi · bayar di tempat</button><button class="btn btn-s" data-act="pay" data-v="LUNAS">Sudah bayar ${rp(b.total)}</button>`
      :sk==='DP'?`<button class="btn btn-p" data-act="pay" data-v="DP">${ICON.lock}DP ${rp(dp)} diterima</button><button class="btn btn-s" data-act="pay" data-v="LUNAS">Lunas ${rp(b.total)} diterima</button>`
      :`<button class="btn btn-p" data-act="pay" data-v="LUNAS">${ICON.lock}Lunas ${rp(b.total)} diterima</button>${st.dpAktif?`<button class="btn btn-s" data-act="pay" data-v="DP">Baru DP ${rp(dp)}</button>`:''}`;
    main=`<div class="inline-pick"><b>${sk==='TUNAI'?'Pasien pilih bayar tunai. Konfirmasi jadwalnya?':'Cek pembayaran masuk, lalu kunci jadwal'}</b>${sk==='TUNAI'?'':metChips}<div class="btn-row">${btns}</div></div>`;
    more=`<button class="btn btn-s btn-sm" data-act="mode" data-v="batal">Tolak / batalkan</button>`;
  }else if(b.status==='DP'||b.status==='DIKONFIRMASI'){
    main=`<div class="inline-pick"><b>Sisa tagihan ${rp(b.bayar.sisa)}</b>${metChips}<div class="btn-row"><button class="btn btn-p" data-act="pay" data-v="LUNAS">Terima ${b.status==='DP'?'pelunasan':'pembayaran'} ${rp(b.bayar.sisa)}</button></div><small class="muted">Setelah lunas, sesi bisa ditandai selesai.</small></div>`;more=ops;
  }else if(b.status==='LUNAS'){
    main=`<div class="btn-row"><button class="btn btn-ok" data-act="selesai">${ICON.check}Tandai sesi selesai</button></div>`;more=ops;
  }else if(b.status==='KEDALUWARSA'){
    main=`<div class="inline-pick"><b>Waktu tahan sudah habis</b><span class="muted">Kalau pasien ternyata sudah bayar, aktifkan lagi selama jamnya masih kosong.</span><div class="btn-row"><button class="btn btn-p" data-act="aktif">Aktifkan lagi</button></div></div>`;
  }
  return `${main}<div class="btn-row">${wa}${more}</div>`;
}
